using System.IO;
using System.Text.RegularExpressions;
using UnityEditor;
using UnityEditor.Build;
using UnityEditor.Build.Reporting;
using UnityEngine;
using OCS.VR.Experience;

namespace OCS.VR.EditorTools
{
    /// <summary>
    /// Catches the experience scene being older than the builder before it costs anyone
    /// time. The scene is generated by OCS > Build Experience Scene and stamped with
    /// ExperienceSequencer.SceneVersion; pulling new code without rebuilding leaves the old
    /// layout playing with the new data, which looks broken rather than out of date.
    ///
    /// Pressing Play on a stale scene offers to rebuild it first. Building the player with
    /// a stale scene fails, with the fix in the message, so an old scene never reaches the
    /// headset.
    /// </summary>
    [InitializeOnLoad]
    public static class SceneVersionCheck
    {
        const string ScenePath = "Assets/Scenes/Experience.unity";

        static SceneVersionCheck()
        {
            EditorApplication.playModeStateChanged += OnPlayModeChanged;
        }

        static void OnPlayModeChanged(PlayModeStateChange change)
        {
            if (change != PlayModeStateChange.ExitingEditMode) return;
            ExperienceSequencer sequencer = Object.FindAnyObjectByType<ExperienceSequencer>();
            if (sequencer == null || sequencer.builtWithSceneVersion >= ExperienceSequencer.SceneVersion) return;

            int choice = EditorUtility.DisplayDialogComplex("The experience scene is out of date",
                "This scene was built by an older version of the scene builder, so it would play the old layout. " +
                "Rebuild it now? (OCS > Build Experience Scene)",
                "Rebuild and play", "Cancel", "Play the old one");
            if (choice == 2) return;

            EditorApplication.isPlaying = false;          // stop this Play; it would run the old scene
            if (choice != 0) return;
            EditorApplication.delayCall += () =>
            {
                ExperienceSceneBuilder.BuildScene();
                EditorApplication.isPlaying = true;
            };
        }

        /// <summary>The version stamped in the saved scene, or -1 when it has none.</summary>
        public static int SavedSceneVersion()
        {
            if (!File.Exists(ScenePath)) return -1;
            Match m = Regex.Match(File.ReadAllText(ScenePath), @"builtWithSceneVersion:\s*(\d+)");
            return m.Success ? int.Parse(m.Groups[1].Value) : -1;
        }

        /// <summary>Stops a player build that would ship an old scene.</summary>
        public class BuildGuard : IPreprocessBuildWithReport
        {
            public int callbackOrder => 0;

            public void OnPreprocessBuild(BuildReport report)
            {
                if (!File.Exists(ScenePath)) return;
                int saved = SavedSceneVersion();
                if (saved >= ExperienceSequencer.SceneVersion) return;
                throw new BuildFailedException(
                    "Assets/Scenes/Experience.unity was built by an older scene builder (version " + saved +
                    ", current " + ExperienceSequencer.SceneVersion + "), so the headset would get the old layout. " +
                    "Run OCS > Build Experience Scene, then build again.");
            }
        }
    }
}
